// Sorted input. Current version uses O(n) extra space (a Set).
// Rewrite dedup to be in-place, O(1) auxiliary space.
function dedup(arr) {
  const seen = new Set();
  const out = [];
  for (const x of arr) {
    if (!seen.has(x)) { seen.add(x); out.push(x); }
  }
  return out;
}

console.log(JSON.stringify(dedup([1, 1, 2, 3, 3, 3, 5])));
